async function mineOneLog(bot) {
  const logNames = ["oak_log", "birch_log", "spruce_log", "jungle_log", "acacia_log", "dark_oak_log", "mangrove_log"];

  // Check if we already have a log in inventory
  for (const name of logNames) {
    const item = bot.inventory.findInventoryItem(mcData.itemsByName[name].id);
    if (item) {
      bot.chat(`Already have ${name}, no need to mine.`);
      return;
    }
  }

  // Try to find a log nearby
  let logBlock = bot.findBlock({
    matching: block => logNames.includes(block.name),
    maxDistance: 32
  });
  if (!logBlock) {
    bot.chat("No log nearby, exploring...");
    const directions = [new Vec3(1, 0, 0), new Vec3(-1, 0, 0), new Vec3(0, 0, 1), new Vec3(0, 0, -1), new Vec3(1, 0, 1), new Vec3(-1, 0, -1)];
    const dir = directions[Math.floor(Math.random() * directions.length)];
    logBlock = await exploreUntil(bot, dir, 60, () => {
      return bot.findBlock({
        matching: block => logNames.includes(block.name),
        maxDistance: 32
      });
    });
  }
  if (!logBlock) {
    bot.chat("Failed to find any log.");
    return;
  }
  bot.chat(`Found ${logBlock.name}, mining...`);
  await mineBlock(bot, logBlock.name, 1);
  bot.chat("Mined 1 log.");
}
await mineOneLog(bot);

async function mineJungleLogs(bot) {
  const targetCount = 3;
  const logName = "jungle_log";

  // Count existing jungle logs in inventory
  const existing = bot.inventory.items().filter(item => item.name === logName).reduce((sum, item) => sum + item.count, 0);
  let remaining = targetCount - existing;
  if (remaining <= 0) {
    bot.chat(`Already have ${existing} ${logName}, no need to mine.`);
    return;
  }
  bot.chat(`Need ${remaining} more ${logName}.`);
  while (remaining > 0) {
    // Try to find a nearby jungle log
    let logBlock = bot.findBlock({
      matching: block => block.name === logName,
      maxDistance: 32
    });
    if (!logBlock) {
      bot.chat("No jungle log nearby, exploring...");
      const directions = [new Vec3(1, 0, 0), new Vec3(-1, 0, 0), new Vec3(0, 0, 1), new Vec3(0, 0, -1), new Vec3(1, 0, 1), new Vec3(-1, 0, -1), new Vec3(1, 0, -1), new Vec3(-1, 0, 1)];
      const dir = directions[Math.floor(Math.random() * directions.length)];
      logBlock = await exploreUntil(bot, dir, 60, () => {
        return bot.findBlock({
          matching: block => block.name === logName,
          maxDistance: 32
        });
      });
    }
    if (!logBlock) {
      bot.chat("Failed to find any jungle log.");
      return;
    }
    bot.chat(`Found ${logName}, mining...`);
    await mineBlock(bot, logName, remaining);

    // Recount after mining
    const nowCount = bot.inventory.items().filter(item => item.name === logName).reduce((sum, item) => sum + item.count, 0);
    remaining = targetCount - nowCount;
    if (remaining > 0) {
      bot.chat(`Still need ${remaining} more ${logName}.`);
    }
  }
  bot.chat(`Done mining ${targetCount} ${logName}.`);
}
await mineJungleLogs(bot);

async function craftCraftingTable(bot) {
  // Check if we already have a crafting table
  const existing = bot.inventory.findInventoryItem(mcData.itemsByName["crafting_table"].id);
  if (existing) {
    bot.chat("Already have a crafting table.");
    return;
  }

  // Ensure we have at least 4 jungle_planks
  let planks = bot.inventory.items().filter(i => i.name === "jungle_planks").reduce((s, i) => s + i.count, 0);
  if (planks < 4) {
    const needed = 4 - planks;
    const logsNeeded = Math.ceil(needed / 4);
    const logs = bot.inventory.items().filter(i => i.name === "jungle_log").reduce((s, i) => s + i.count, 0);
    if (logs < logsNeeded) {
      bot.chat("Not enough jungle logs, mining more...");
      await mineBlock(bot, "jungle_log", logsNeeded - logs);
    }
    bot.chat("Crafting jungle planks...");
    await craftItem(bot, "jungle_planks", logsNeeded);
  }
  bot.chat("Crafting crafting table...");
  await craftItem(bot, "crafting_table", 1);
  bot.chat("Crafted 1 crafting table.");
}
await craftCraftingTable(bot);

async function craftWoodenPickaxe(bot) {
  const plankNames = ["oak_planks", "birch_planks", "spruce_planks", "jungle_planks", "acacia_planks", "dark_oak_planks", "mangrove_planks", "cherry_planks", "bamboo_planks", "crimson_planks", "warped_planks"];
  const logNames = ["oak_log", "birch_log", "spruce_log", "jungle_log", "acacia_log", "dark_oak_log", "mangrove_log", "cherry_log"];

  // 1) Ensure we have a crafting_table item in inventory
  let tableItem = bot.inventory.findInventoryItem(mcData.itemsByName["crafting_table"].id);
  if (!tableItem) {
    bot.chat("No crafting table item, crafting one...");
    let plankCount = bot.inventory.items().filter(i => plankNames.includes(i.name)).reduce((s, i) => s + i.count, 0);
    if (plankCount < 4) {
      let logItem = bot.inventory.items().find(i => logNames.includes(i.name));
      if (!logItem) {
        bot.chat("No logs, mining one...");
        await mineOneLog(bot);
        logItem = bot.inventory.items().find(i => logNames.includes(i.name));
      }
      if (!logItem) {
        bot.chat("Failed to obtain a log.");
        return;
      }
      const plankName = logItem.name.replace("_log", "_planks");
      await craftItem(bot, plankName, 1);
    }
    await craftItem(bot, "crafting_table", 1);
    tableItem = bot.inventory.findInventoryItem(mcData.itemsByName["crafting_table"].id);
  }

  // 2) Ensure a crafting_table block exists nearby; if not, place it
  let tableBlock = bot.findBlock({
    matching: mcData.blocksByName.crafting_table.id,
    maxDistance: 32
  });
  if (!tableBlock) {
    bot.chat("Placing crafting table...");
    const pos = bot.entity.position.offset(1, 0, 0);
    await placeItem(bot, "crafting_table", pos);
    tableBlock = bot.findBlock({
      matching: mcData.blocksByName.crafting_table.id,
      maxDistance: 32
    });
    if (!tableBlock) {
      bot.chat("Failed to place crafting table.");
      return;
    }
  }

  // 3) Ensure we have 3 planks and 2 sticks
  let plankCount = bot.inventory.items().filter(i => plankNames.includes(i.name)).reduce((s, i) => s + i.count, 0);
  if (plankCount < 3) {
    let logItem = bot.inventory.items().find(i => logNames.includes(i.name));
    if (!logItem) {
      bot.chat("Not enough planks, mining a log...");
      await mineOneLog(bot);
      logItem = bot.inventory.items().find(i => logNames.includes(i.name));
    }
    if (!logItem) {
      bot.chat("Failed to obtain a log.");
      return;
    }
    const plankName = logItem.name.replace("_log", "_planks");
    await craftItem(bot, plankName, 1);
  }
  let stickCount = bot.inventory.items().filter(i => i.name === "stick").reduce((s, i) => s + i.count, 0);
  if (stickCount < 2) {
    bot.chat("Crafting sticks...");
    await craftItem(bot, "stick", 1);
  }

  // 4) Craft the wooden pickaxe
  bot.chat("Crafting wooden pickaxe...");
  await craftItem(bot, "wooden_pickaxe", 1);
  bot.chat("Crafted 1 wooden pickaxe.");
}
await craftWoodenPickaxe(bot);

