  // 1) Ensure we have a suitable pickaxe (stone or better)
  let hasPickaxe = bot.inventory.items().some(i => pickaxeNames.includes(i.name));
  if (!hasPickaxe) {
    bot.chat("No suitable pickaxe (stone or better) found. Cannot mine iron ore.");
    return;
  }

  // 2) Count existing raw_iron
  let ironCount = bot.inventory.items().filter(i => i.name === "raw_iron").reduce((s, i) => s + i.count, 0);
  let remaining = targetCount - ironCount;
  if (remaining <= 0) {
    bot.chat(`Already have ${ironCount} raw iron, no need to mine.`);
    return;
  }
  bot.chat(`Need ${remaining} more iron ore.`);

  // 3) Mine iron ore until we have enough
  let attempts = 0;
  while (remaining > 0 && attempts < 10) {
    attempts++;
    let ironBlock = bot.findBlock({
      matching: mcData.blocksByName["iron_ore"].id,
      maxDistance: 32
    });
    if (!ironBlock) {
      bot.chat("No iron ore nearby, exploring downward...");
      const directions = [new Vec3(0, -1, 0), new Vec3(1, -1, 0), new Vec3(-1, -1, 0), new Vec3(0, -1, 1), new Vec3(0, -1, -1), new Vec3(1, -1, 1), new Vec3(-1, -1, -1)];
      const dir = directions[Math.floor(Math.random() * directions.length)];
      ironBlock = await exploreUntil(bot, dir, 60, () => {
        return bot.findBlock({
          matching: mcData.blocksByName["iron_ore"].id,
          maxDistance: 32
        });
      });
    }
    if (!ironBlock) {
      bot.chat("Failed to find any iron ore.");
      return;
    }
    bot.chat("Found iron ore, mining...");
    await mineBlock(bot, "iron_ore", remaining);
    ironCount = bot.inventory.items().filter(i => i.name === "raw_iron").reduce((s, i) => s + i.count, 0);
    remaining = targetCount - ironCount;
    if (remaining > 0) {
      bot.chat(`Still need ${remaining} more iron ore.`);
    }
  }
  bot.chat(`Done mining iron ore. Total raw iron: ${ironCount}.`);
}
await mineIronOre(bot);

async function smeltRawIron(bot) {
  const targetCount = 3;

  // 1) Check raw_iron in inventory
  let rawIronCount = bot.inventory.items().filter(i => i.name === "raw_iron").reduce((s, i) => s + i.count, 0);
  if (rawIronCount < targetCount) {
    bot.chat(`Not enough raw_iron (${rawIronCount}/${targetCount}). Cannot smelt.`);
    return;
  }

  // 2) Ensure we have fuel (coal or charcoal)
  let fuelName = null;
  const coalCount = bot.inventory.items().filter(i => i.name === "coal").reduce((s, i) => s + i.count, 0);
  const charcoalCount = bot.inventory.items().filter(i => i.name === "charcoal").reduce((s, i) => s + i.count, 0);
  if (coalCount > 0) fuelName = "coal";else if (charcoalCount > 0) fuelName = "charcoal";
  if (!fuelName) {
    bot.chat("No coal or charcoal available as fuel. Cannot smelt.");
    return;
  }

  // 3) Ensure a furnace block is nearby; otherwise place one from inventory
  let furnaceBlock = bot.findBlock({
    matching: mcData.blocksByName.furnace.id,
    maxDistance: 32
  });
  if (!furnaceBlock) {
    const furnaceItem = bot.inventory.findInventoryItem(mcData.itemsByName["furnace"].id);
    if (!furnaceItem) {
      bot.chat("No furnace item in inventory and no furnace nearby. Cannot smelt.");
      return;
    }
    bot.chat("Placing furnace...");
    // Try a few candidate positions around the bot
    const offsets = [new Vec3(1, 0, 0), new Vec3(-1, 0, 0), new Vec3(0, 0, 1), new Vec3(0, 0, -1), new Vec3(1, 0, 1), new Vec3(-1, 0, -1)];
    for (const off of offsets) {
      const pos = bot.entity.position.offset(off.x, off.y, off.z).floored();
      try {
        await placeItem(bot, "furnace", pos);
      } catch (e) {
        continue;
      }
      furnaceBlock = bot.findBlock({
        matching: mcData.blocksByName.furnace.id,
        maxDistance: 32
      });
      if (furnaceBlock) break;
    }
    if (!furnaceBlock) {
      bot.chat("Failed to place furnace.");
      return;
    }
  }

  // 4) Smelt the raw iron
  bot.chat(`Smelting ${targetCount} raw_iron using ${fuelName}...`);
  await smeltItem(bot, "raw_iron", fuelName, targetCount);
  const ingotCount = bot.inventory.items().filter(i => i.name === "iron_ingot").reduce((s, i) => s + i.count, 0);
  bot.chat(`Done. Total iron_ingot: ${ingotCount}.`);
}
await smeltRawIron(bot);

