      // try to reposition slightly and look again
      try {
        await bot.pathfinder.goto(new GoalGetToBlock(chestPosition.x, chestPosition.y, chestPosition.z));
        await bot.lookAt(chestPosition.offset(0.5, 0.5, 0.5), true);
      } catch (_) {}
      await bot.waitForTicks(20);
    }
  }
  if (!chest) {
    bot.chat("Could not open the chest after multiple attempts.");
    return;
  }

  // 6) Deposit exactly targetCount cobblestone
  try {
    let remaining = targetCount;
    while (remaining > 0) {
      const item = bot.inventory.findInventoryItem(mcData.itemsByName["cobblestone"].id);
      if (!item) break;
      const amount = Math.min(remaining, item.count);
      await chest.deposit(item.type, null, amount);
      remaining -= amount;
    }
    bot.chat(`Deposited ${targetCount - remaining} cobblestone.`);
  } catch (e) {
    bot.chat(`Error while depositing: ${e.message}`);
  } finally {
    chest.close();
  }

  // 7) Report remaining
  cobbleCount = countCobble();
  bot.chat(`Done. Remaining cobblestone in inventory: ${cobbleCount}`);
}
